mapper.select:
SELECT FROM resource r LEFT JOIN resource_category c ON r.category_id = c.id LEFT JOIN ( SELECT resource_id, COUNT(*) AS favorite_count FROM resource_favorite GROUP BY resource_id ) fav_count ON r.id = fav_count.resource_id
r.category_id = #{categoryId}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))
AND r.visibility = #{visibility}
AND r.owner_id = #{ownerId}
ORDER BY r.created_at DESC

mapper.update:
UPDATE resource
title = #{title}, category_id = #{categoryId}, description = #{description}, file_url = #{fileUrl}, owner_name = #{ownerName}, like_count = #{likeCount}, download_count = #{downloadCount}, view_count = #{viewCount}, visibility = #{visibility}, allow_download = #{allowDownload}, updated_at = NOW()
WHERE id = #{id}
